                    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px">
                        <span style="font-size:10px;font-weight:700;color:var(--or);background:var(--or-pale);border:1px solid var(--or-border);padding:2px 7px;border-radius:10px">SEO</span>
                        <span style="font-size:10px;font-weight:700;color:var(--or);background:var(--or-pale);border:1px solid var(--or-border);padding:2px 7px;border-radius:10px">AEO</span>
                        <span style="font-size:10px;font-weight:700;color:var(--or);background:var(--or-pale);border:1px solid var(--or-border);padding:2px 7px;border-radius:10px">GEO</span>
                        <span style="font-size:10px;font-weight:700;color:var(--or);background:var(--or-pale);border:1px solid var(--or-border);padding:2px 7px;border-radius:10px">AI Search</span>
                        <span style="font-size:10px;font-weight:700;color:var(--or);background:var(--or-pale);border:1px solid var(--or-border);padding:2px 7px;border-radius:10px">Technical SEO</span>
                    </div>
                </div>
            </div>
