                    <a href="https://linkedin.com/in/mohamed-yahia-249265134/" target="_blank" style="width:32px;height:32px;border-radius:var(--rs);background:var(--sur);border:1px solid var(--brd);display:flex;align-items:center;justify-content:center;color:var(--mu);transition:all .2s" onmouseover="this.style.borderColor='var(--or)';this.style.color='var(--or)'" onmouseout="this.style.borderColor='var(--brd)';this.style.color='var(--mu)'"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" style="flex-shrink:0"><path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z"/><rect x="2" y="9" width="4" height="12"/><circle cx="4" cy="4" r="2"/></svg></a>
                    <a href="mailto:mohamedyahia702@gmail.com" style="width:32px;height:32px;border-radius:var(--rs);background:var(--sur);border:1px solid var(--brd);display:flex;align-items:center;justify-content:center;color:var(--mu);transition:all .2s" onmouseover="this.style.borderColor='var(--or)';this.style.color='var(--or)'" onmouseout="this.style.borderColor='var(--brd)';this.style.color='var(--mu)'"><i data-lucide="mail" style="width:14px;height:14px;stroke:currentColor;fill:none"></i></a>
