                <span class="en">© 2025 Mohamed Yahia — All Rights Reserved</span>
            </div>
            <div style="display:flex;gap:16px">
                <button onclick="showPage('page-about')" style="background:none;border:none;font-size:11px;color:var(--mu);cursor:pointer;font-family:inherit;transition:color .2s" onmouseover="this.style.color='var(--or)'" onmouseout="this.style.color='var(--mu)'">
