                </button>
                <button onclick="sc('services')" style="background:none;border:none;font-size:11px;color:var(--mu);cursor:pointer;font-family:inherit;transition:color .2s" onmouseover="this.style.color='var(--or)'" onmouseout="this.style.color='var(--mu)'">
                    <span class="ar">الخدمات</span><span class="en">Services</span>
