                <button onclick="sc('contact')" style="background:none;border:none;font-size:11px;color:var(--mu);cursor:pointer;font-family:inherit;transition:color .2s" onmouseover="this.style.color='var(--or)'" onmouseout="this.style.color='var(--mu)'">
                    <span class="ar">تواصل</span><span class="en">Contact</span>
